import { Injectable } from "@angular/core";
import { HttpClient } from "@angular/common/http";
import { Router } from "@angular/router";
import { factura } from "../pages/ventas/venta";
import { environment } from "src/environments/environment";

@Injectable({
  providedIn: "root",
})
export class ServicioWebVeronicaService {
  venta: factura[];
  //private URL = 'http://localhost:3000/servicioWebVeronica'; //localhost
  //private URL = "http://159.223.107.115:3000/servicioWebVeronica";
  private URL = `${environment.services.urlServices}/servicioWebVeronica`;
  constructor(public http: HttpClient, public router: Router) {}

  newLog(log) {
    return this.http.post<any>(this.URL + "/newLog", log);
  }

  getLogsVeronica(objFecha) {
    return this.http.post(this.URL + "/getLogsVeronica", objFecha);
  }

  getLogsVeronicaPorFactura(objetoBusqueda,nroDocumento) {
    return this.http.post(this.URL + `/getLogsVeronicaPorFactura/${nroDocumento}`, objetoBusqueda);
  }

  updateEstadoLog(logVeronica, estado: string) {
    return this.http.put(this.URL + `/updateEstadoLog/${logVeronica._id}/${estado}`, logVeronica);
  }
}
